STORAGE_LIMIT = 262_144
LOW, HIGH = -(1 << 63), (1 << 63) - 1
IMMEDIATE = {"PUSH", "JUMP", "BRANCH", "CALL"}
PLAIN = {"DUP", "DROP", "SWAP", "LOAD", "STORE", "ADD", "SUB", "EQ", "LT", "LE",
         "NOT", "AND", "OR", "RETURN", "ALLOC", "FREE", "HALT"}


