        self.mark("bootstrap_loop"); self.emit("DUP"); self.jump("BRANCH", "bootstrap_body")
        self.emit("DROP"); self.emit("PUSH", 1); self.emit("ADD")
        self.emit("PUSH", 1024); self.emit("SWAP"); self.emit("SUB"); self.emit("ALLOC"); self.emit("DROP")
